WFI.Data.add("quest", {
  [78088] = { "Uno strano manufatto", "Porta l'Althalaxx Orb a Delgren the Purifier, al Maestra's Post di Ashenvale.", "<La sfera misteriosa che stringi ti riempie di un terrore gelido. Ti sembra quasi di sentire una voce riecheggiare debolmente nella tua mente. Bassa e gutturale: capisci bene che la lingua parlata è di natura demoniaca.\n\nAnche per <un/una> <paladino/paladina>, questa magia va oltre le tue capacità. Trova qui a Kalimdor un paladino di grado più alto che possa aiutarti a capire la natura di questo oggetto sinistro.>", nil, nil, 0x54d84c8e, 0xf162540c, 0x00ddba1f, nil, nil, "...mm" },
  [78089] = { "Consigli da Stormwind", "Porta l'Althalaxx Orb a Katherine the Pure, a Stormwind.", "C'è un'oscurità potente in questa sfera. La sua natura è chiaramente demoniaca, ma oltre questo non sono in grado di capirne lo scopo.\n\nPorta la sfera a colei che è nota come Katherine the Pure, nella Stormwind Cathedral. Chiedile consiglio sulla sfera.", nil, nil, 0x5e36a76b, 0x3b4d2dbd, 0x789ee65c, nil, nil, "...mm" },
  [78090] = { "Un secondo parere", "Trova il santuario degli stregoni a Stormwind e chiedi consiglio sulla sfera.", "Non so cosa pensare di questa sfera, {name}. Credo che ci servirà l'aiuto di... uno specialista.\n\nSappiamo di una setta di stregoni che opera a Stormwind. Ufficialmente respingiamo la presenza di stregoni in città. Ufficiosamente, le loro conoscenze possono essere utili quando si ha a che fare con forze demoniache.\n\nTrova un rappresentante di questi stregoni e chiedi la loro opinione sulla sfera.", nil, nil, 0x87bb7435, 0x7c900333, 0x547fdd46, nil, nil, "...mm" },
  [78091] = { "Guadagnarsi il sale", "Raccogli 14 Summoner's Salt dai Blackrock Summoner delle Redridge Mountains, poi torna da Ursula Deline, a Stormwind.", "Studierò la sfera e ti dirò cosa scopro, ma prima devi fare qualcosa per me.\n\nGli stregoni del clan Blackrock usano sali preparati in modo speciale per potenziare i loro rituali di evocazione. Raccoglienne un po' dagli orchi di Redridge.\n\nQuando tornerai, condividerò con te i risultati dei miei studi.", nil, nil, 0x7d78a823, 0x1de3212f, 0xd4dd5884, nil, nil, "...mm" },
  [78092] = { "Va distrutto", "Raccogli 12 Motes of Mannoroth dai demoni di Ashenvale. Portali insieme all'Orb of Althalaxx allo Spear of Mannoroth, nel Demon Fall Canyon.", "I tentacoli di coscienza che si protendono da questa sfera sono troppo persino per uno stregone esperto come me per resistervi a lungo. Mi costa ammetterlo, {name}, ma la sfera va distrutta.\n\nLa sfera è quasi indistruttibile, ma potrebbe essere vulnerabile all'arma di un potente signore dei demoni. Ho sentito che una lama del genere si trova ad Ashenvale, nel luogo in cui fu distrutto il pit lord Mannoroth.\n\nRaccogli lì frammenti dell'essenza del demone caduto, poi frantuma la sfera sulla lama.", nil, nil, 0x725d212a, 0x5fdc36a4, 0x72f2a6fa, nil, nil, "...mm" },
  [78127] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", nil, nil, nil, nil, 0x1400fbf0, nil, "mmm.m" },
  [78142] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", nil, nil, nil, nil, 0x1400fbf0, nil, "mmm.m" },
  [78143] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", nil, nil, nil, nil, 0x1400fbf0, nil, "mmm.m" },
  [78145] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", nil, nil, nil, nil, 0x1400fbf0, nil, "mmm.m" },
  [78149] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", nil, nil, nil, nil, 0x1400fbf0, nil, "mmm.m" },
  [78261] = { nil, "Trova The Horn of Xelthos dentro Shadowfang Keep. Poi riportalo al nascondiglio di C vicino al Pyrewood Village. Devi portare a termine il lavoro da <solo/sola>.", "<Nel forziere c'è un biglietto>\n\nSalve, {name}.\n\nDesidero un tesoro noto come The Horn of Xelthos, che si trova da qualche parte dentro Shadowfang Keep.\n\nAvventurarsi nella fortezza di solito richiede rinforzi. Per questo lavoro, però, la discrezione è della massima importanza.\n\nDevi andare da <solo/sola>.\n\nHo un contatto, di nome Veenix, nelle Stonetalon Mountains. Dovrebbe poterti aiutare a superare il cancello del cortile. Il resto dipende da te.\n\nRiporta qui il corno e il tuo pagamento ti sarà mandato subito dopo.\n\n- C", nil, nil, nil, 0xa04dc89a, 0x3eb0aa8f, nil, nil, "m..mm" },
  [78270] = { "Grimaldelli goblin", "Trova The Horn of Xelthos dentro Shadowfang Keep. Poi riportalo al nascondiglio di C vicino al Pyrewood Village.", "<Nel forziere c'è un biglietto>\n\nSalve di nuovo, {name}.\n\nDesidero un tesoro noto come The Horn of Xelthos, che si trova da qualche parte dentro Shadowfang Keep.\n\nAvventurarsi nella fortezza di solito richiede rinforzi. Per questo lavoro, però, la discrezione è della massima importanza.\n\nDevi andare da <solo/sola>.\n\nHo un contatto, di nome Veenix, nelle Stonetalon Mountains. Dovrebbe poterti aiutare a superare il cancello del cortile. Il resto dipende da te.\n\nRiporta qui il corno e il tuo pagamento ti sarà mandato subito dopo.\n\n- C", nil, nil, 0x6567783d, 0x8f719ff2, 0xe73ec883, nil, nil, "...mm" },
  [78916] = { "Il cuore del vuoto", "Porta la Blackfathom Pearl al Dawnwatcher Selgorm, a Darnassus.", "La temibile bestia Aku'mai giace morta. Nascosta tra le viscere e il sangue del suo cadavere gonfio c'è un'enorme perla iridescente che brulica di pura energia del vuoto.", nil, nil, 0xc885df05, 0x864e71af, 0x0a93b80a, nil, nil, "...mm" },
  [78917] = { "Il cuore del vuoto", nil, "La temibile bestia Aku'mai giace morta. Nascosta tra le viscere e il sangue del suo cadavere gonfio c'è un'enorme perla iridescente che brulica di pura energia del vuoto.", nil, nil, 0xc885df05, nil, 0x0a93b80a, nil, nil, ".m.mm" },
})
